=====harness.c=====
     1	/*
     2	 * Independent oracle harness.
     3	 *
     4	 * Replays two labeled capture files through the agent-written filter and
     5	 * scores it. This is the authoritative verification — the backend runs it
     6	 * on human-prepared, held-out fixtures the agent never sees.
     7	 *
     8	 *   argv[1] = attack capture  (every frame SHOULD be blocked -> expect true)
     9	 *   argv[2] = benign capture   (every frame should PASS       -> expect false)
    10	 *
    11	 * Fixture format: one frame per line as hex (e.g. "c000...").
    12	 * Blank lines and lines starting with '#' are ignored.
    13	 *
    14	 * The agent's filter is dropped next to this file as filter.c and must define:
    15	 *   bool block_frame(const uint8_t *f, size_t n);
    16	 *
    17	 * Output (machine-parseable, last line is authoritative):
    18	 *   TPR=1.000 FPR=0.000 PASSED=8 TOTAL=8
    19	 *   RESULT=PASS
    20	 */
    21	#include <ctype.h>
    22	#include <stdbool.h>
    23	#include <stddef.h>
    24	#include <stdint.h>
    25	#include <stdio.h>
    26	#include <string.h>
    27	
    28	#include "filter.c"
    29	
    30	#define MAX_LINE 8192
    31	#define MAX_FRAME 4096
    32	
    33	/* Parse one hex line into bytes. Returns frame length, or -1 to skip. */
    34	static int parse_hex(const char *line, uint8_t *out, size_t cap) {
    35	    size_t n = 0;
    36	    int hi = -1;
    37	    for (const char *p = line; *p; ++p) {
    38	        char c = *p;
    39	        if (c == '#') break;              /* inline comment */
    40	        if (isspace((unsigned char)c)) continue;
    41	        if (c == '_' || c == ':' || c == '-') continue;  /* readability seps */
    42	        int v;
    43	        if (c >= '0' && c <= '9') v = c - '0';
    44	        else if (c >= 'a' && c <= 'f') v = c - 'a' + 10;
    45	        else if (c >= 'A' && c <= 'F') v = c - 'A' + 10;
    46	        else return -1;                   /* junk -> skip line */
    47	        if (hi < 0) {
    48	            hi = v;
    49	        } else {
    50	            if (n >= cap) return (int)n;
    51	            out[n++] = (uint8_t)((hi << 4) | v);
    52	            hi = -1;
    53	        }
    54	    }
    55	    if (n == 0) return -1;                 /* blank/comment line */
    56	    return (int)n;
    57	}
    58	
    59	/* Run the filter over a file. expect_block=true for attack, false for benign.
    60	 * Increments *correct for each frame classified as expected, *total per frame. */
    61	static int score_file(const char *path, bool expect_block, int *correct, int *total) {
    62	    FILE *fp = fopen(path, "r");
    63	    if (!fp) {
    64	        fprintf(stderr, "oracle: cannot open %s\n", path);
    65	        return -1;
    66	    }
    67	    char line[MAX_LINE];
    68	    uint8_t frame[MAX_FRAME];
    69	    while (fgets(line, sizeof line, fp)) {
    70	        int len = parse_hex(line, frame, sizeof frame);
    71	        if (len < 0) continue;
    72	        bool blocked = block_frame(frame, (size_t)len);
    73	        *total += 1;
    74	        if (blocked == expect_block) *correct += 1;
    75	    }
    76	    fclose(fp);
    77	    return 0;
    78	}
    79	
    80	int main(int argc, char **argv) {
    81	    if (argc < 3) {
    82	        fprintf(stderr, "usage: %s <attack.hex> <benign.hex>\n", argv[0]);
    83	        return 2;
    84	    }
    85	
    86	    int tp = 0, attack_total = 0;   /* attack frames correctly blocked */
    87	    int tn = 0, benign_total = 0;   /* benign frames correctly passed  */
    88	
    89	    if (score_file(argv[1], true, &tp, &attack_total) < 0) return 2;
    90	    if (score_file(argv[2], false, &tn, &benign_total) < 0) return 2;
    91	
    92	    int fn = attack_total - tp;     /* attacks that slipped through */
    93	    int fp = benign_total - tn;     /* legit frames wrongly blocked */
    94	
    95	    double tpr = attack_total ? (double)tp / attack_total : 0.0;
    96	    double fpr = benign_total ? (double)fp / benign_total : 0.0;
    97	
    98	    int total = attack_total + benign_total;
    99	    int passed = tp + tn;
   100	
   101	    /* Pass = catches every attack AND blocks nothing legit. */
   102	    bool ok = (fn == 0) && (fp == 0) && (attack_total > 0);
   103	
   104	    printf("TPR=%.3f FPR=%.3f PASSED=%d TOTAL=%d\n", tpr, fpr, passed, total);
   105	    printf("RESULT=%s\n", ok ? "PASS" : "FAIL");
   106	    return ok ? 0 : 1;
   107	}
=====deauth.c=====
     1	/*
     2	 * Sample filter — the shape the agent (Devin) is expected to emit.
     3	 *
     4	 * Blocks 802.11 management deauthentication / disassociation frames, the
     5	 * payload of a deauth/disassoc flood. The first byte of an 802.11 frame is
     6	 * the Frame Control field: bits [7:4] = subtype, bits [3:2] = type.
     7	 *
     8	 *   type 00 = management
     9	 *   subtype 1100 (0xC) = deauthentication  -> FC = 0xC0
    10	 *   subtype 1010 (0xA) = disassociation    -> FC = 0xA0
    11	 *
    12	 * Data (0x08) and beacon (0x80) frames pass untouched.
    13	 */
    14	#include <stdbool.h>
    15	#include <stddef.h>
    16	#include <stdint.h>
    17	
    18	bool block_frame(const uint8_t *f, size_t n) {
    19	    if (n < 1) return false;
    20	    uint8_t fc = f[0];
    21	    uint8_t type = (fc >> 2) & 0x3;
    22	    uint8_t subtype = (fc >> 4) & 0xF;
    23	    if (type != 0x0) return false;                 /* only management frames */
    24	    return subtype == 0xC || subtype == 0xA;       /* deauth or disassoc     */
    25	}
